import { Property } from '@stitches/react/types/css';

export type LoadingStatusType = 'uploading' | 'uploaded' | 'error' | 'feedback';

export interface UploadableFile {
  id: string;
  name: string;
  size: number;
  type: string;
  fileContent: File;
  loadingStatus: LoadingStatusType;
  progress: number;
  errors?: string[];
  url?: string;
}

export interface FileMultiUploaderType {
  value?: UploadableFile[];
  size?: 'small' | 'large';
  disabled?: boolean;
  title?: string;
  message?: string;
  inputLabel?: string;
  imageFit?: Property.ObjectFit;
  multiple?: boolean;
  maxFileSize?: number;
  accept?: string;
  feedbackMessage?: string;
  feedbackTimeout?: number;
  hasPreviewButton?: boolean;
  hasProgress?: boolean;
  inputId?: string;
  onDrop?: (files: UploadableFile[]) => void;
  onChange?: (files: UploadableFile[]) => void;
  onPreview?: (file: UploadableFile) => void;
  onProgress?: (setProgress: (percentage: number) => void) => void;
  onClean?: (file: UploadableFile) => void;
  onUpload?: (file: UploadableFile) => void;
  uploadFile?: (file: File, setProgress?: (percentage: number) => void) => Promise<string>;
  customFileValidator?: (file: File) => string[];
}

export interface Validation {
  errorMessage: string;
  validation: (file: File) => boolean;
}

export interface DragAndDropAreaProps {
  onDrop: (filesDropped: File[]) => void;
  disabled: boolean;
  title?: string;
  message?: string;
  inputLabel?: string;
  multiple: boolean;
  accept?: string;
  ref?: React.ForwardedRef<HTMLDivElement>;
  size?: 'small' | 'large';
  id?: string;
}

export interface FileListItemType {
  file: UploadableFile;
  feedbackMessage?: string;
  feedbackTimeout?: number;
  imageFit?: Property.ObjectFit;
  hasPreviewButton: boolean;
  hasProgress: boolean;
  size?: 'small' | 'large';
  setLoadingStatus: (id: string, loadingStatus: LoadingStatusType) => void;
  setProgress: (id: string, progress: number) => void;
  setErrors: (id: string, errors: string[]) => void;
  onClean?: (file: UploadableFile) => void;
  onUpload: (file: UploadableFile, url: string) => void;
  uploadFile?: (file: File, onProgress: (percentage: number) => void) => Promise<string>;
  onProgress?: (onProgress: (progress: number) => void) => void;
  onPreview?: (file: UploadableFile) => void;
}
